from PIL import Image
import numpy as np
I=np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
R,G,B=I.transpose(2,0,1)
ms={
 K:V for K,V in {
 'K':(R<50)&(G<50)&(B<55),
 'P':(R>145)&(R-G>40)&(R-B>35)&(G>65)&(B>60),
 'U':(B-R>35)&(B-G>18)&(B>80),
 'R':(R>120)&(R-G>60)&(R-B>70)&(G<70),
 'Y':(R>145)&(G>105)&(B<40)&(R-G>15),
 }.items()}
def runs(a, xmin=60,xmax=160):
 inds=np.where(a[xmin:xmax])[0]+xmin
 if not len(inds):return '-'
 out=[]; st=pr=inds[0]
 for x in inds[1:]:
  if x>pr+1:out.append((st,pr));st=x
  pr=x
 out.append((st,pr))
 return ','.join(f'{a}-{b}' for a,b in out)
for y in range(0,116):
 vals=[runs(ms[k][y]) for k in 'KPURY']
 if any(x"'!='"'-' for x in vals): print(f'{y:03} K:{vals[0]:17} P:{vals[1]:17} U:{vals[2]:17} R:{vals[3]:17} Y:{vals[4]}')
PY"

